contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance > 0, "need funds");
        require(target != address(0), "target zero");
        uint before = address(c).balance;
        require(before > 0, "c has no balance");
        uint amount = address(c).balance;
        c.withdraw(amount); if (__ESBMC_reverted()) return;
        uint balAfterWithdraw = address(c).balance;
        require(balAfterWithdraw == 0, "withdraw failed");
        require(address(this).balance > 0, "no funds for sendMoney");
        uint send = 0;
        bool reverted;
        c.sendMoney(target, send, ""); if (__ESBMC_reverted()) return;
        reverted = false;
        require(!reverted, "sendMoney reverted");
        uint finalBal = address(c).balance;
        assert(finalBal == balAfterWithdraw);
    }

    receive() external payable {}
}

