// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address target) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance > 0);
        vm.assume(target != address(0));
        uint before = address(c).balance;
        vm.assume(before > 0);
        uint amount = address(c).balance;
        try c.withdraw(amount) {} catch { return; }
        uint balAfterWithdraw = address(c).balance;
        vm.assume(balAfterWithdraw == 0);
        vm.assume(address(this).balance > 0);
        uint send = 0;
        bool reverted;
        try c.sendMoney(target, send, "") {} catch { return; }
        reverted = false;
        vm.assume(!reverted);
        uint finalBal = address(c).balance;
        assertTrue(finalBal == balAfterWithdraw);
    }

    function testFuzz_run(address target) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(target);
    }

    receive() external payable {}
}
